 static async Task<int> Run(string root,string output){
  HermesWatchConsent.TestRoot=root;string config=Path.Combine(root,@"data\hybrid-native-001\workbench-config.json"),folder=Path.Combine(root,@"data\hybrid-native-001\user-consent"),lockFile=Path.Combine(root,@"data\hybrid-native-001\native-worker-hermes.lock");int prepares=0,starts=0;var order=new List<string>();
