  string consent=File.ReadAllText(started.ConsentPath);Check(consent.Contains("\"source\":\"FAKE_TEST_ONLY\"")&&consent.Contains("\"externalAudit\":false")&&consent.Contains("\"roleEnableStillSeparate\":true")&&consent.Contains("8D5C0176C5495D85F53F3EE9F30B3D3821F83E6E358FE9174BF26ADFDD7E90CE"),"Consent scope/source/hash record missing");
  var resultFile=started.ConsentPath.Replace(".consent.json",".start-result.json");Check(File.ReadAllText(resultFile).Contains("\"connectionVerified\":false")&&File.ReadAllText(resultFile).Contains("\"enableGranted\":false"),"Process signal became connection or enable");
